{"path":"/root/solve.py","content":"#!/usr/bin/env python3
import csv
import json
from datetime import datetime
from pathlib import Path

ROOT = Path('/root')


def is_blank(value):
    if value is None:
        return True
    text = str(value).strip()
    return text == '' or text.lower() == 'nan'


def money(value):
    return float(round(float(value) + 0.0, 2))


def load_csv(name):
    with (ROOT / name).open(newline='') as f:
        return list(csv.DictReader(f))


def flatten_campaigns(manifest):
    if isinstance(manifest, list):
        return manifest
    if isinstance(manifest, dict):
        if isinstance(manifest.get('campaigns'), list):
            return manifest['campaigns']
        campaigns = []
        for region in manifest.get('regions', []):
            campaigns.extend(region.get('campaigns', []))
        return campaigns
    raise ValueError('campaign_manifest.json must contain a JSON array or object')


def cycle_key(tag):
    text = str(tag).strip()
    for fmt in ('%Y-%m-%d', '%Y/%m/%d', '%Y%m%d'):
        try:
            return (1, datetime.strptime(text, fmt))
        except ValueError:
            pass
    return (0, text)


def main():
    with (ROOT / 'campaign_manifest.json').open() as f:
        manifest = json.load(f)

    all_campaigns = flatten_campaigns(manifest)
    crate_rows = load_csv('crate_cost.csv')
    billing_rows = load_csv('billing.csv')
    override_rows = load_csv('location_overrides.csv')
    suspension_rows = load_csv('suspensions.csv')

    hold_ids = {
        row.get('campaign_id', '').strip()
        for row in suspension_rows
        if row.get('suspension_status', '').strip() == 'hold'
    }

    campaigns = [
        c for c in all_campaigns
        if c.get('analysis_flag') == 'review' and c.get('campaign_id') not in hold_ids
    ]

    crate_costs = {
        row['crate_tier'].strip(): float(row['crate_cost_usd'])
        for row in crate_rows
        if not is_blank(row.get('crate_tier')) and not is_blank(row.get('crate_cost_usd'))
    }

    valid_overrides = {}
    for row in override_rows:
        if row.get('state', '').strip() != 'approved':
            continue
        if is_blank(row.get('revision')) or is_blank(row.get('active_clinics')):
            continue
        cid = row.get('campaign_id', '').strip()
        revision = float(row['revision'])
        active_clinics = int(float(row['active_clinics']))
        if cid not in valid_overrides or revision > valid_overrides[cid]['revision']:
            valid_overrides[cid] = {
                'revision': revision,
                'active_clinics': active_clinics,
            }

    active_billing = [
        row for row in billing_rows
        if row.get('status', '').strip() == 'active'
    ]

    campaign_outputs = []
    for campaign in campaigns:
        cid = campaign['campaign_id']
        labels = {campaign.get('campaign_name', '')}
        aliases = campaign.get('alias_labels') or []
        if not isinstance(aliases, list):
            aliases = [aliases]
        labels.update(str(label) for label in aliases)

        matches = [
            row for row in active_billing
            if row.get('campaign_label', '') in labels
        ]
        if matches:
            billing = max(matches, key=lambda row: cycle_key(row.get('cycle_tag', '')))
            payment = float(billing['payment_per_dispatch_per_clinic_usd'])
        else:
            print(f"WARNING: no active billing row found for {cid}")
            payment = 0.0

        if cid in valid_overrides:
            active_clinics = valid_overrides[cid]['active_clinics']
        else:
            active_clinics = int(campaign['default_active_clinics'])

        crate_tier = campaign['crate_tier']
        if crate_tier not in crate_costs:
            raise ValueError(f"Missing crate cost for tier {crate_tier!r}")
        crate_cost = crate_costs[crate_tier]

        drug_cost = float(campaign['drug_cost_per_1000_doses_usd'])
        doses_per_day = float(campaign['doses_per_day'])

        annual_revenue_6 = payment * active_clinics * 60
        annual_drug_cost_6 = drug_cost * active_clinics * doses_per_day * 6 * 60 / 1000
        annual_crate_cost_6 = crate_cost * 60
        annual_margin_6 = annual_revenue_6 - annual_drug_cost_6 - annual_crate_cost_6

        annual_revenue_12 = payment * active_clinics * 30
        annual_drug_cost_12 = drug_cost * active_clinics * doses_per_day * 12 * 30 / 1000
        annual_crate_cost_12 = crate_cost * 30
        annual_margin_12 = annual_revenue_12 - annual_drug_cost_12 - annual_crate_cost_12

        difference = annual_margin_12 - annual_margin_6

        campaign_outputs.append({
            'campaign_id': cid,
            'campaign_name': campaign['campaign_name'],
            'active_clinics': active_clinics,
            'crate_tier': crate_tier,
            'crate_cost_usd': money(crate_cost),
            'payment_per_dispatch_per_clinic_usd': money(payment),
            'annual_revenue_6': money(annual_revenue_6),
            'annual_drug_cost_6': money(annual_drug_cost_6),
            'annual_crate_cost_6': money(annual_crate_cost_6),
            'annual_margin_6': money(annual_margin_6),
            'annual_revenue_12': money(annual_revenue_12),
            'annual_drug_cost_12': money(annual_drug_cost_12),
            'annual_crate_cost_12': money(annual_crate_cost_12),
            'annual_margin_12': money(annual_margin_12),
            'difference': money(difference),
        })

    campaign_outputs.sort(key=lambda row: row['campaign_id'])

    total_margin_6 = money(sum(row['annual_margin_6'] for row in campaign_outputs))
    total_margin_12 = money(sum(row['annual_margin_12'] for row in campaign_outputs))
    total_difference = money(sum(row['difference'] for row in campaign_outputs))
    abs_diff = money(abs(total_difference))
    threshold = 11000.00
    decision = 'move_to_12_day' if abs_diff < threshold else 'keep_6_day'

    analysis = {
        'assumptions': {
            'days_per_dispatch_6': 6,
            'dispatches_per_year_6': 60,
            'days_per_dispatch_12': 12,
            'dispatches_per_year_12': 30,
            'decision_threshold_usd': 11000.00,
        },
        'campaigns': campaign_outputs,
        'totals': {
            'total_margin_6': total_margin_6,
            'total_margin_12': total_margin_12,
            'total_difference': total_difference,
            'abs_diff': abs_diff,
        },
        'decision': decision,
        'justification': f"Absolute difference is ${abs_diff:.2f}, compared with the $11000.00 threshold; decision is {decision}.",
    }

    with (ROOT / 'vaxcrate_analysis.json').open('w') as f:
        json.dump(analysis, f, indent=2)
        f.write('\n')

    summary_lines = [
        '# VaxCrate Dispatch Analysis Summary',
        f'Total 6-day margin (USD): ${total_margin_6:.2f}',
        f'Total 12-day margin (USD): ${total_margin_12:.2f}',
        f'Absolute difference (USD): ${abs_diff:.2f}',
        f'Decision: {decision}',
    ]
    with (ROOT / 'vaxcrate_summary.md').open('w') as f:
        f.write('\n'.join(summary_lines) + '\n')


if __name__ == '__main__':
    main()
